// ─── File: ShardKeyDemo.java ───
// Runnable demo: compare shard keys — opening-date & region cause HOT SHARDS; customerId balances.
package com.bank.shardkey;

import java.util.*;
import java.util.function.Function;
import java.util.logging.*;

public class ShardKeyDemo {

    private static final Logger log = Logger.getLogger("ShardKey");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Skewed realistic data: most customers in Maharashtra, all opened "today".
        List<Customer> customers = new ArrayList<>();
        for (int i = 1; i <= 100; i++) {
            String region = i <= 80 ? "Maharashtra" : (i <= 95 ? "Karnataka" : "Goa");
            customers.add(new Customer("CUST" + (1000 + i), region, "2026-10-24"));
        }

        // BAD key 1: opening date → ALL on one shard (monotonic hot shard).
        evaluate("openingDate", c -> c.openingDate, customers);
        // BAD key 2: region → low cardinality, skew → hot shard.
        evaluate("region", c -> c.region, customers);
        // GOOD key: customerId → high cardinality, even spread + per-customer locality.
        evaluate("customerId", c -> c.customerId, customers);
    }

    static void evaluate(String keyName, Function<Customer, String> keyFn, List<Customer> customers) {
        ShardCluster cluster = new ShardCluster(4, keyFn);
        for (Customer c : customers) cluster.insert(c);
        int[] dist = cluster.distribution();
        int max = Arrays.stream(dist).max().orElse(0);
        int total = Arrays.stream(dist).sum();
        // Scalability is capped by the BUSIEST shard's share.
        double hotShardShare = 100.0 * max / total;
        log.info(() -> "key='" + keyName + "' distribution=" + Arrays.toString(dist)
                + " → busiest shard holds " + String.format("%.0f", hotShardShare) + "% of data"
                + (hotShardShare > 40 ? "  ← HOT SHARD caps scalability" : "  ← balanced"));
    }
}

// ─── model/Customer.java ───
class Customer {
    final String customerId, region, openingDate;
    Customer(String id, String region, String openingDate) {
        this.customerId = id; this.region = region; this.openingDate = openingDate;
    }
}

// ─── cluster/ShardCluster.java (routes by a configurable shard-key extractor) ───
class ShardCluster {
    private final int n;
    private final Function<Customer, String> keyFn;
    private final List<List<Customer>> shards = new ArrayList<>();
    ShardCluster(int n, Function<Customer, String> keyFn) {
        this.n = n; this.keyFn = keyFn;
        for (int i = 0; i < n; i++) shards.add(new ArrayList<>());
    }
    void insert(Customer c) {
        String key = keyFn.apply(c);
        int shard = Math.floorMod(key.hashCode(), n);   // hash the chosen key
        shards.get(shard).add(c);
    }
    int[] distribution() { return shards.stream().mapToInt(List::size).toArray(); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
